package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class TotpBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String name="AuthenticatorBrowser"+id();try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",name,"password",WorkflowSupport.PASSWORD,"role","agent"));db.connection.commit();}
  try(var playwright=Playwright.create();var browser=playwright.chromium().launch();var context=browser.newContext()) {
   var page=context.newPage();h.login(page,name);page.navigate(h.base()+"/account");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Authenticator and recovery codes").setExact(true)).press("Enter");page.getByLabel("Current local password").fill(WorkflowSupport.PASSWORD);ServiceOutagesBrowserAcceptance.click(page,"Create authenticator setup");String key=page.getByLabel("Manual setup key").inputValue();assertEquals(32,key.length());assertTrue(page.getByLabel("Authenticator setup URI").inputValue().contains(key));ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/authenticator-setup-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(p=>p.scrollWidth>p.clientWidth+1)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/authenticator-setup-dark.png")).setFullPage(true));
   page.getByLabel("Authenticator code",new Page.GetByLabelOptions().setExact(true)).fill(TotpAcceptance.otp(key,System.currentTimeMillis()));ServiceOutagesBrowserAcceptance.click(page,"Confirm authenticator");assertThat(page.locator("main")).containsText("Existing sessions have ended");var codes=page.locator("main li code").allTextContents();assertEquals(10,codes.size());ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/authenticator-recovery-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Sign in again").setExact(true)).press("Enter");page.getByLabel("Username",new Page.GetByLabelOptions().setExact(true)).fill(name);page.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);ServiceOutagesBrowserAcceptance.click(page,"Enter your workspace →");page.waitForURL(h.base()+"/mfa");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/authenticator-challenge-dark.png")).setFullPage(true));page.getByLabel("Authenticator or recovery code").fill(codes.get(0));ServiceOutagesBrowserAcceptance.click(page,"Verify and sign in");page.waitForURL(h.base()+"/");page.navigate(h.base()+"/account/mfa");assertThat(page.locator("main")).containsText("Unused recovery codes: 9");assertThat(page.locator("main li code")).hasCount(0);assertThat(page.getByLabel("Manual setup key")).hasCount(0);
   page.getByLabel("Current local password").fill(WorkflowSupport.PASSWORD);page.getByLabel("Fresh authenticator or recovery code").fill(codes.get(1));page.getByLabel("Security change").selectOption("disable");ServiceOutagesBrowserAcceptance.click(page,"Apply security change");assertThat(page.locator("main")).containsText("Authenticator not enabled");h.login(page,name);page.navigate(h.base()+"/account/mfa");assertThat(page.locator("main")).containsText("Set up an authenticator");try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_totp WHERE user_id=?",TotpAcceptance.user(db,name).get("user_id")));}
  }
 }
}
